1	/**
2	 * Run-local CPU-only geometry feasibility probe for the Common Ground arena.
3	 *
4	 * Read-only. Imports shipped pure modules; never mutates source, never renders,
5	 * never starts a server. Reproduce with:
6	 *
7	 *   cd /home/thomasphillip/Projects/vox/main \
8	 *     && npx vite-node ../.codex/story-runs/2026-09-06-common-ground/geometry-feasibility-probe.mts \
9	 *     > ../.codex/story-runs/2026-09-06-common-ground/geometry-feasibility.json
10	 *
11	 * All geometry is derived from the SAME functions the runtime uses:
12	 *   createResolvedWorldGenerator  (utils/resolvedWorldGenerator.ts)
13	 *   createStoryAnchorResolver     (story/world/storyAnchorResolver.ts)
14	 *   planAgentSurfaceRoute         (utils/agentSurfaceNavigation.ts)
15	 *   groundedSurfaceRouteLength    (utils/groundedSurfaceMotion.ts)
16	 * with the worker route options copied verbatim from
17	 * story/emergentStoryDirector.ts::moveAuditor (lines ~2225-2234).
18	 *
19	 * Caveat recorded in the report: this uses the PRISTINE procedural terrain
20	 * query, not createLiveAgentSurfaceTerrain (which needs voxelSystem/live edits
21	 * and therefore a running client). Results are source-derived for an unedited
22	 * world.
23	 */
24	import * as THREE from 'three';
25	import { createResolvedWorldGenerator } from '../../../main/src/utils/resolvedWorldGenerator.ts';
26	import { createStoryAnchorResolver } from '../../../main/src/story/world/storyAnchorResolver.ts';
27	import { STORY_SEED, STORY_PRIMARY_WORLD_ID, STORY_COORDINATE } from '../../../main/src/story/world/storyWorldIdentity.ts';
28	import { planAgentSurfaceRoute, type AgentSurfaceTerrainQuery } from '../../../main/src/utils/agentSurfaceNavigation.ts';
29	import { groundedSurfaceRouteLength } from '../../../main/src/utils/groundedSurfaceMotion.ts';
30	import { VOXEL_SCALE, voxelCoordToWorld } from '../../../main/src/utils/cubeGravityConstants.ts';
31	import { buildTreeProfile } from '../../../main/src/utils/treeProfile.ts';
32	
33	const PLANET_SIZE = 50; // components/EfficientScene.tsx::planetSize
34	const UP = new THREE.Vector3(0, 1, 0);
35	
36	// story/emergentStoryDirector.ts::moveAuditor — verbatim.
37	const WORKER_ROUTE_OPTIONS = {
38	  face: 'top' as const,
39	  differentFaceFallback: 'unreachable' as const,
40	  clearanceCells: 2,
41	  maxSlopeCells: 1,
42	  edgeMarginCells: 1,
43	  maxVisitedCells: 8192,
44	  waypointClearanceWorld: 1.05,
45	  allowJetpackCrossing: false
46	};
47	
48	// chapter-story-treatment.md#proposed-bounded-trace-contract
49	const MAX_TRACE_POINTS = 128;
50	const MAX_TRACE_LENGTH = 120;
51	const SAMPLE_SPACING = 1.0;
52	const MIN_SAMPLE_SEPARATION = 0.25;
53	
54	const { generator } = createResolvedWorldGenerator({
55	  worldId: STORY_PRIMARY_WORLD_ID,
56	  seed: STORY_SEED,
57	  planetRadius: PLANET_SIZE / 2
58	});
59	const voxels = generator.getAllVoxelPositions();
60	const resolver = createStoryAnchorResolver({ generator, voxels });
61	
62	const terrain: AgentSurfaceTerrainQuery = {
63	  isSolidVoxel: (x, y, z) => generator.shouldVoxelExist(x, y, z),
64	  isWaterVoxel: (x, y, z) => generator.isWaterVoxel(x, y, z),
65	  isHazardousVoxel: (x, y, z) => generator.generateBlockForPosition(x, y, z) === 'lava'
66	};
67	
68	const v3 = (v: THREE.Vector3) => ({ x: +v.x.toFixed(3), y: +v.y.toFixed(3), z: +v.z.toFixed(3) });
69	
70	// --- anchors ---------------------------------------------------------------
71	const tree = resolver.getHeroTreePose(PLANET_SIZE, STORY_SEED);
72	const pond = resolver.getPondPose(PLANET_SIZE, STORY_SEED);
73	const relay = resolver.getWreckRelayPose(PLANET_SIZE, STORY_SEED);
74	const mesa = resolver.getSignalMesaPose(PLANET_SIZE, STORY_SEED);
75	const pod = resolver.getPodImpactPose(PLANET_SIZE, STORY_SEED);
76	const pack = resolver.getFieldPackPose(PLANET_SIZE, STORY_SEED, terrain);
77	const auditPath = resolver.getAuditWorkerPath(PLANET_SIZE, STORY_SEED, terrain);
78	
79	if (!pond) throw new Error('probe: no pond pose on the pinned story world');
80	
81	// trunk collider: HeroAppleTree.tsx:190 CuboidCollider args [0.55, h/2, 0.55]
82	const heroProfile = buildTreeProfile((STORY_SEED ^ 0xede9) >>> 0);
83	const trunkHeight = Math.max(heroProfile.trunkHeight, 7.2);
84	const TRUNK_HALF = 0.55;
85	
86	// --- terrain helpers -------------------------------------------------------
87	function columnTop(vx: number, vz: number): number | null {
88	  const limit = Math.floor(PLANET_SIZE / 2) + 6;
89	  for (let y = limit; y >= 0; y--) if (terrain.isSolidVoxel(vx, y, vz)) return y;
90	  return null;
91	}
92	function dryStandable(vx: number, vz: number): { y: number; world: THREE.Vector3 } | null {
93	  const y = columnTop(vx, vz);
94	  if (y === null) return null;
95	  if (terrain.isWaterVoxel(vx, y + 1, vz)) return null;
96	  if (terrain.isWaterVoxel(vx, y + 2, vz)) return null;
97	  if (terrain.isHazardousVoxel!(vx, y, vz)) return null;
98	  // worker clearanceCells = 2
99	  if (terrain.isSolidVoxel(vx, y + 1, vz) || terrain.isSolidVoxel(vx, y + 2, vz)) return null;
100	  return { y, world: voxelCoordToWorld(vx, y, vz).addScaledVector(UP, VOXEL_SCALE / 2 + 0.05) };
101	}
102	const toVoxel = (p: THREE.Vector3) => ({ x: Math.round(p.x / VOXEL_SCALE), z: Math.round(p.z / VOXEL_SCALE) });
103	
104	// --- occlusion truth (terrain voxels + trunk collider box) -----------------
105	const EYE = 1.6;
106	function trunkBlocks(a: THREE.Vector3, b: THREE.Vector3): boolean {
107	  // 2D segment vs axis-aligned square around the trunk, with a height gate.
108	  const t = tree.position;
109	  if (Math.min(a.y, b.y) > t.y + trunkHeight) return false;
110	  const steps = Math.ceil(a.distanceTo(b) / 0.2);
111	  for (let i = 0; i <= steps; i++) {
112	    const p = a.clone().lerp(b, i / steps);
113	    if (Math.abs(p.x - t.x) <= TRUNK_HALF && Math.abs(p.z - t.z) <= TRUNK_HALF
114	      && p.y >= t.y && p.y <= t.y + trunkHeight) return true;
115	  }
116	  return false;
117	}
118	function terrainBlocks(a: THREE.Vector3, b: THREE.Vector3): boolean {
119	  const steps = Math.ceil(a.distanceTo(b) / 0.35);
120	  for (let i = 1; i < steps; i++) {
121	    const p = a.clone().lerp(b, i / steps);
122	    const vx = Math.round(p.x / VOXEL_SCALE);
123	    const vy = Math.round(p.y / VOXEL_SCALE);
124	    const vz = Math.round(p.z / VOXEL_SCALE);
125	    if (terrain.isSolidVoxel(vx, vy, vz)) return true;
126	  }
127	  return false;
128	}
129	/**
130	 * Near-field exemption: inside one voxel of the reference the eye ray leaves
131	 * through the reference's own support column, which the DDA reports as a hit.
132	 * That is a probe artifact, not an occluder, so it is reported separately.
133	 */
134	const NEAR_FIELD = 3.0;
135	function witnessLine(a: THREE.Vector3, b: THREE.Vector3) {
136	  const ea = a.clone().addScaledVector(UP, EYE);
137	  const eb = b.clone().addScaledVector(UP, EYE);
138	  const horizontal = Math.hypot(ea.x - eb.x, ea.z - eb.z);
139	  const distance = +ea.distanceTo(eb).toFixed(2);
140	  if (horizontal < NEAR_FIELD) return { clear: true, nearField: true, byTerrain: false, byTrunk: false, distance };
141	  const byTerrain = terrainBlocks(ea, eb);
142	  const byTrunk = trunkBlocks(ea, eb);
143	  return { clear: !byTerrain && !byTrunk, nearField: false, byTerrain, byTrunk, distance };
144	}
145	
146	// --- trace sampling rule ---------------------------------------------------
147	function traceSamples(points: THREE.Vector3[]): THREE.Vector3[] {
148	  const out: THREE.Vector3[] = [];
149	  if (points.length === 0) return out;
150	  out.push(points[0].clone());
151	  let last = points[0].clone();
152	  let lastHeading: THREE.Vector3 | null = null;
153	  for (let i = 1; i < points.length; i++) {
154	    const a = points[i - 1];
155	    const b = points[i];
156	    const segLen = a.distanceTo(b);
157	    const heading = b.clone().sub(a).setY(0).normalize();
158	    const turned = lastHeading ? heading.dot(lastHeading) < Math.cos(Math.PI / 12) : false;
159	    let travelled = 0;
160	    while (travelled < segLen) {
161	      const need = turned && last.distanceTo(a) >= MIN_SAMPLE_SEPARATION ? MIN_SAMPLE_SEPARATION : SAMPLE_SPACING;
162	      const remaining = need - last.distanceTo(a.clone().lerp(b, travelled / segLen));
163	      const step = Math.max(0.05, remaining);
164	      travelled += step;
165	      if (travelled > segLen) break;
166	      const p = a.clone().lerp(b, travelled / segLen);
167	      if (p.distanceTo(last) >= MIN_SAMPLE_SEPARATION) { out.push(p); last = p.clone(); }
168	    }
169	    lastHeading = heading;
170	  }
171	  const end = points[points.length - 1];
172	  if (end.distanceTo(last) > 1e-3) out.push(end.clone());
173	  return out;
174	}
175	
176	function plan(from: THREE.Vector3, to: THREE.Vector3) {
177	  return planAgentSurfaceRoute(terrain, PLANET_SIZE, from, to, WORKER_ROUTE_OPTIONS);
178	}
179	
180	interface Leg { mode: string; reason: string; waypoints: THREE.Vector3[]; visited: number }
181	function legOf(from: THREE.Vector3, to: THREE.Vector3): Leg {
182	  const r = plan(from, to);
183	  return { mode: r.mode, reason: r.reason, waypoints: r.waypoints, visited: r.visitedCells };
184	}
185	
186	function evaluateRoute(name: string, legs: Leg[], reference: THREE.Vector3) {
187	  const waypoints: THREE.Vector3[] = [];
188	  for (const leg of legs) {
189	    for (const w of leg.waypoints) {
190	      if (waypoints.length && waypoints[waypoints.length - 1].distanceTo(w) < 1e-4) continue;
191	      waypoints.push(w.clone());
192	    }
193	  }
194	  const length = groundedSurfaceRouteLength(waypoints.map(position => ({ position })), UP);
195	  const samples = traceSamples(waypoints);
196	  const los = samples.map(p => witnessLine(p, reference));
197	  const blocked = los.filter(l => !l.clear);
198	  const firstBlockedIndex = los.findIndex(l => !l.clear);
199	  const nearField = los.filter(l => l.nearField).length;
200	  return {
201	    name,
202	    legs: legs.map(l => ({ mode: l.mode, reason: l.reason, waypoints: l.waypoints.length, visitedCells: l.visited })),
203	    walkable: legs.every(l => l.mode === 'walk'),
204	    waypointCount: waypoints.length,
205	    walkedLength: +length.toFixed(2),
206	    lengthWithinBudget: length <= MAX_TRACE_LENGTH,
207	    traceSampleCount: samples.length,
208	    pointsWithinBudget: samples.length <= MAX_TRACE_POINTS,
209	    witnessReference: v3(reference),
210	    witnessNearFieldExemptSamples: nearField,
211	    witnessClearSamples: samples.length - blocked.length,
212	    witnessBlockedSamples: blocked.length,
213	    witnessBlockedByTerrain: blocked.filter(b => b.byTerrain).length,
214	    witnessBlockedByTrunk: blocked.filter(b => b.byTrunk).length,
215	    firstBlockedSampleIndex: firstBlockedIndex,
216	    firstBlockedSamplePosition: firstBlockedIndex >= 0 ? v3(samples[firstBlockedIndex]) : null,
217	    maxWitnessDistance: +Math.max(...los.map(l => l.distance)).toFixed(2),
218	    endpoints: { start: v3(waypoints[0]), end: v3(waypoints[waypoints.length - 1]) }
219	  };
220	}
221	
222	// --- endpoints -------------------------------------------------------------
223	// Start reference: the dry standable column beside the wreck relay (the
224	// treatment's "wreck/relay as the approach").
225	function nearestDry(seed: THREE.Vector3, maxRadius = 8, minDistance = 0) {
226	  const s = toVoxel(seed);
227	  for (let r = 0; r <= maxRadius; r++) {
228	    let best: { d: number; p: THREE.Vector3 } | null = null;
229	    for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
230	      if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
231	      const hit = dryStandable(s.x + dx, s.z + dz);
232	      if (!hit) continue;
233	      if (hit.world.distanceTo(seed) < minDistance) continue;
234	      const d = hit.world.distanceTo(seed);
235	      if (!best || d < best.d) best = { d, p: hit.world };
236	    }
237	    if (best) return best.p;
238	  }
239	  return null;
240	}
241	
242	const relayStand = nearestDry(relay.position);
243	const endRef = nearestDry(pond.shore);
244	// The reference must stand CLEAR of the trunk collider, otherwise every witness
245	// line trivially intersects the trunk box it originates inside.
246	const treeStand = nearestDry(tree.position, 8, 3);
247	if (!relayStand || !endRef || !treeStand) throw new Error('probe: could not resolve dry endpoints');
248	// chapter-story-treatment.md#arena-and-the-initial-contradiction:
249	// the arena is tree <-> pond shore; the wreck/relay is only the approach.
250	const startRef = treeStand;
251	
252	// --- Route A: shortest planner answer (the "shorter bend" candidate) -------
253	const routeA = evaluateRoute('A-direct-shorter', [legOf(startRef, endRef)], startRef);
254	
255	// --- Route B: outer detour around the far side of the tree ------------------
256	// Deterministic detour selection: ring of dry standable columns at radius 8-14
257	// voxels from the tree, on the opposite side of the straight start->end line,
258	// choosing the candidate that yields the longest fully-walkable route still
259	// inside the 120-unit / 128-point budget.
260	const straight = endRef.clone().sub(startRef).setY(0).normalize();
261	const sideNormal = new THREE.Vector3().crossVectors(UP, straight).normalize();
262	const detourCandidates: Array<{ p: THREE.Vector3; offset: number; radius: number }> = [];
263	const tv = toVoxel(tree.position);
264	for (let r = 6; r <= 14; r++) {
265	  for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
266	    if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
267	    const hit = dryStandable(tv.x + dx, tv.z + dz);
268	    if (!hit) continue;
269	    const offset = hit.world.clone().sub(startRef).dot(sideNormal);
270	    detourCandidates.push({ p: hit.world, offset, radius: r });
271	  }
272	}
273	detourCandidates.sort((a, b) => Math.abs(b.offset) - Math.abs(a.offset));
274	
275	let routeB: ReturnType<typeof evaluateRoute> | null = null;
276	let detourUsed: THREE.Vector3 | null = null;
277	let detoursTried = 0;
278	const rejections = { notWalkable: 0, overLengthBudget: 0, overPointBudget: 0, notLonger: 0, witnessBroken: 0 };
279	let bestRejected: ReturnType<typeof evaluateRoute> | null = null;
280	for (const candidate of detourCandidates.slice(0, 60)) {
281	  detoursTried++;
282	  const leg1 = legOf(startRef, candidate.p);
283	  if (leg1.mode !== 'walk') { rejections.notWalkable++; continue; }
284	  const leg2 = legOf(candidate.p, endRef);
285	  if (leg2.mode !== 'walk') { rejections.notWalkable++; continue; }
286	  const evaluated = evaluateRoute('B-outer-detour', [leg1, leg2], startRef);
287	  if (!evaluated.lengthWithinBudget) { rejections.overLengthBudget++; if (!bestRejected) bestRejected = evaluated; continue; }
288	  if (!evaluated.pointsWithinBudget) { rejections.overPointBudget++; if (!bestRejected) bestRejected = evaluated; continue; }
289	  if (evaluated.walkedLength <= routeA.walkedLength * 1.15) { rejections.notLonger++; continue; }
290	  if (evaluated.witnessBlockedSamples > 0) rejections.witnessBroken++;
291	  // Keep the longest budget-legal walkable detour; prefer zero witness breaks.
292	  const better = !routeB
293	    || (routeB.witnessBlockedSamples > 0 && evaluated.witnessBlockedSamples === 0)
294	    || (routeB.witnessBlockedSamples === 0) === (evaluated.witnessBlockedSamples === 0)
295	      && evaluated.walkedLength > routeB.walkedLength;
296	  if (better) { routeB = evaluated; detourUsed = candidate.p; }
297	}
298	
299	// --- occlusion census: can this corridor's terrain occlude a witness line? --
300	const corridorMin = { x: Math.min(startRef.x, endRef.x) - 20, z: Math.min(startRef.z, endRef.z) - 20 };
301	const corridorMax = { x: Math.max(startRef.x, endRef.x) + 20, z: Math.max(startRef.z, endRef.z) + 20 };
302	let censusDry = 0, censusBlockedTerrain = 0, censusBlockedTrunk = 0;
303	const blockedExamples: unknown[] = [];
304	for (let wx = corridorMin.x; wx <= corridorMax.x; wx += VOXEL_SCALE) {
305	  for (let wz = corridorMin.z; wz <= corridorMax.z; wz += VOXEL_SCALE) {
306	    const hit = dryStandable(Math.round(wx / VOXEL_SCALE), Math.round(wz / VOXEL_SCALE));
307	    if (!hit) continue;
308	    censusDry++;
309	    const line = witnessLine(hit.world, startRef);
310	    if (line.byTerrain) { censusBlockedTerrain++; if (blockedExamples.length < 5) blockedExamples.push({ from: v3(hit.world), distance: line.distance }); }
311	    if (line.byTrunk) censusBlockedTrunk++;
312	  }
313	}
314	
315	// --- Intermediate witness feasibility for the shorter route ----------------
316	// If route A has blocked samples, does a single dry standable position exist
317	// that sees BOTH the blocked span and the start reference?
318	let intermediateWitness: unknown = null;
319	if (routeA.firstBlockedSampleIndex >= 0 && routeA.firstBlockedSamplePosition) {
320	  const blockedPoint = new THREE.Vector3(
321	    routeA.firstBlockedSamplePosition.x,
322	    routeA.firstBlockedSamplePosition.y,
323	    routeA.firstBlockedSamplePosition.z
324	  );
325	  const mid = blockedPoint.clone().add(startRef).multiplyScalar(0.5);
326	  const mv = toVoxel(mid);
327	  let found: { p: THREE.Vector3; toStart: number; toBlocked: number } | null = null;
328	  for (let r = 0; r <= 10 && !found; r++) {
329	    for (let dx = -r; dx <= r && !found; dx++) for (let dz = -r; dz <= r && !found; dz++) {
330	      if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
331	      const hit = dryStandable(mv.x + dx, mv.z + dz);
332	      if (!hit) continue;
333	      const a = witnessLine(hit.world, startRef);
334	      const b = witnessLine(hit.world, blockedPoint);
335	      if (a.clear && b.clear) found = { p: hit.world, toStart: a.distance, toBlocked: b.distance };
336	    }
337	  }
338	  intermediateWitness = found
339	    ? { exists: true, position: v3(found.p), distanceToStartReference: found.toStart, distanceToBlockedSpan: found.toBlocked }
340	    : { exists: false };
341	}
342	
343	const report = {
344	  probe: 'common-ground geometry feasibility',
345	  generatedAt: new Date().toISOString(),
346	  derivation: 'source-derived (pristine procedural terrain; no live voxel edits, no render, no GPU)',
347	  world: {
348	    planetSize: PLANET_SIZE,
349	    storyCoordinate: STORY_COORDINATE,
350	    storySeed: STORY_SEED,
351	    worldId: STORY_PRIMARY_WORLD_ID,
352	    voxelScale: VOXEL_SCALE,
353	    voxelCount: voxels.length
354	  },
355	  workerRouteOptions: WORKER_ROUTE_OPTIONS,
356	  traceContract: { maxPoints: MAX_TRACE_POINTS, maxLengthUnits: MAX_TRACE_LENGTH, sampleSpacing: SAMPLE_SPACING, minSeparation: MIN_SAMPLE_SEPARATION },
357	  anchors: {
358	    heroTree: { position: v3(tree.position), up: v3(tree.up), trunkHeight: +trunkHeight.toFixed(3), trunkColliderHalfExtentXZ: TRUNK_HALF },
359	    pond: { surface: v3(pond.surface), shore: v3(pond.shore), floor: v3(pond.floor), depthVoxels: pond.depth },
360	    wreckRelay: { position: v3(relay.position) },
361	    signalMesa: { position: v3(mesa.position) },
362	    podImpact: { position: v3(pod.position) },
363	    fieldPack: pack ? { position: v3(pack.position), supportVoxel: pack.supportVoxel, relocated: pack.relocated } : null,
364	    auditWorkerPathPoints: auditPath ? auditPath.length : 0
365	  },
366	  derivedEndpoints: {
367	    arenaStartReferenceAtTree: v3(startRef),
368	    approachReferenceNearRelay: v3(relayStand),
369	    relayToTreeDistance: +relayStand.distanceTo(treeStand).toFixed(2),
370	    endReferenceOnPondShore: v3(endRef),
371	    dryStandNearTree: v3(treeStand),
372	    straightStartToEndDistance: +startRef.distanceTo(endRef).toFixed(2),
373	    treeToStartDistance: +tree.position.distanceTo(startRef).toFixed(2),
374	    treeToEndDistance: +tree.position.distanceTo(endRef).toFixed(2),
375	    directStartEndWitnessLine: witnessLine(startRef, endRef)
376	  },
377	  routeA,
378	  routeB,
379	  routeBDetour: detourUsed ? v3(detourUsed) : null,
380	  routeBDetourCandidatesTried: detoursTried,
381	  routeBDetourCandidatePool: detourCandidates.length,
382	  routeBRejections: rejections,
383	  routeBFirstRejectedExample: bestRejected,
384	  intermediateWitnessForRouteA: intermediateWitness,
385	  corridorOcclusionCensus: {
386	    boundsWorld: { min: corridorMin, max: corridorMax },
387	    dryStandableColumns: censusDry,
388	    columnsWithTerrainBlockedWitnessToStart: censusBlockedTerrain,
389	    columnsWithTrunkBlockedWitnessToStart: censusBlockedTrunk,
390	    examples: blockedExamples
391	  }
392	};
393	
394	process.stdout.write(JSON.stringify(report, null, 2) + '\n');
395

