// Column-top ceiling delta over the node field.
const topDelta = (() => {
  let differing = 0, columns = 0;
  for (let u = uLo; u <= uHi; u++) for (let v = vLo; v <= vHi; v++) {
    const s = shippedColumnTop(u, v);
    const p = pass1ColumnTop(u, v);
